import { handleOptions, jsonResponse, errorResponse } from '../_shared/cors.ts';
import { hashWithSalt, normalizeRefCode } from '../_shared/referral-crypto.ts';
import { assertReferralCaller, isReferralInternalCaller } from '../_shared/referral-auth.ts';
import {
  createFraudAlert,
  runFraudChecks,
  type FraudInput,
} from '../_shared/referral-fraud.ts';
import {
  bumpCodeCounters,
  refreshPartnerDaily,
  supabaseService,
} from '../_shared/referral-db.ts';
import {
  markPendingClaimed,
  resolvePendingRefCode,
} from '../_shared/referral-pending.ts';

interface AttributeBody {
  ref_code: string;
  supabase_user_id: string;
  mysql_user_id?: number | null;
  email: string;
  is_new_user: boolean;
  signup_ip?: string;
  device_fp?: string;
  user_agent?: string;
  oauth_provider?: string;
  oauth_subject?: string;
}

Deno.serve(async (req) => {
  const options = handleOptions(req);
  if (options) return options;

  if (req.method !== 'POST') {
    return errorResponse(req, 'Method not allowed', 405);
  }

  try {
    const body = await req.json() as AttributeBody;

    if (!body.supabase_user_id || !body.email) {
      return errorResponse(req, 'supabase_user_id y email requeridos');
    }

    await assertReferralCaller(req, body.supabase_user_id);

    const supabase = supabaseService();

    let refCode = normalizeRefCode(body.ref_code ?? '');
    if (!refCode && body.device_fp) {
      const pending = await resolvePendingRefCode(supabase, body.device_fp);
      if (pending) refCode = pending;
    }

    if (!refCode) {
      return jsonResponse(req, {
        success: true,
        attributed: false,
        reason: 'no_ref_code',
      });
    }

    if (!isReferralInternalCaller(req)) {
      const fp = body.device_fp?.trim() ?? '';
      if (!fp) {
        return jsonResponse(req, {
          success: true,
          attributed: false,
          reason: 'bind_required',
        });
      }
      const boundCode = await resolvePendingRefCode(supabase, fp);
      if (!boundCode || boundCode !== refCode) {
        return jsonResponse(req, {
          success: true,
          attributed: false,
          reason: 'bind_required',
        });
      }
    }

    const { data: codeRow, error: codeErr } = await supabase
      .from('referral_codes')
      .select(`
        id,
        code,
        partner_id,
        is_active,
        expires_at,
        max_signups,
        signup_count,
        referral_partners!inner (
          id,
          display_name,
          is_active
        )
      `)
      .eq('code', refCode)
      .eq('is_active', true)
      .maybeSingle();

    if (codeErr || !codeRow) {
      return jsonResponse(req, {
        success: true,
        attributed: false,
        reason: 'invalid_code',
      });
    }

    const partner = codeRow.referral_partners as {
      id: string;
      display_name: string;
      is_active: boolean;
    };

    if (!partner.is_active) {
      return jsonResponse(req, {
        success: true,
        attributed: false,
        reason: 'partner_inactive',
      });
    }

    if (codeRow.expires_at && new Date(codeRow.expires_at) < new Date()) {
      return jsonResponse(req, {
        success: true,
        attributed: false,
        reason: 'code_expired',
      });
    }

    if (
      codeRow.max_signups != null &&
      (codeRow.signup_count ?? 0) >= codeRow.max_signups
    ) {
      return jsonResponse(req, {
        success: true,
        attributed: false,
        reason: 'code_max_signups',
      });
    }

    const fraudInput: FraudInput = {
      refCode,
      supabaseUserId: body.supabase_user_id,
      mysqlUserId: body.mysql_user_id ?? null,
      email: body.email,
      isNewUser: body.is_new_user !== false,
      signupIp: body.signup_ip ?? '',
      deviceFp: body.device_fp ?? '',
      userAgent: body.user_agent ?? '',
      oauthProvider: body.oauth_provider ?? '',
      oauthSubject: body.oauth_subject ?? '',
    };

    const fraud = await runFraudChecks(supabase, fraudInput, {
      id: codeRow.id,
      partner_id: codeRow.partner_id,
      code: codeRow.code,
    });

    const signupIpHash = await hashWithSalt(fraudInput.signupIp);
    const deviceFpHash = await hashWithSalt(fraudInput.deviceFp);
    const userAgentHash = await hashWithSalt(fraudInput.userAgent);
    const oauthSubjectHash = fraudInput.oauthProvider && fraudInput.oauthSubject
      ? await hashWithSalt(
        `${fraudInput.oauthProvider}:${fraudInput.oauthSubject}`,
      )
      : null;

    const status = fraud.rejected ? 'rejected' : 'valid';
    const signupDate = new Date().toISOString().slice(0, 10);

    const { data: signup, error: insertErr } = await supabase
      .from('referral_signups')
      .insert({
        code_id: codeRow.id,
        partner_id: codeRow.partner_id,
        supabase_user_id: body.supabase_user_id,
        mysql_user_id: body.mysql_user_id ?? null,
        ref_code: refCode,
        partner_display_name: partner.display_name,
        signup_ip_hash: signupIpHash || null,
        device_fp_hash: deviceFpHash || null,
        user_agent_hash: userAgentHash || null,
        oauth_provider: fraudInput.oauthProvider || null,
        oauth_subject_hash: oauthSubjectHash,
        is_new_user: fraudInput.isNewUser,
        status,
        rejection_reason: fraud.rejection_reason,
      })
      .select('id')
      .single();

    if (insertErr) {
      if (insertErr.code === '23505') {
        return jsonResponse(req, {
          success: true,
          attributed: false,
          reason: 'already_attributed',
        });
      }
      throw new Error(insertErr.message);
    }

    if (fraud.flags.length > 0) {
      await supabase.from('referral_flags').insert(
        fraud.flags.map((f) => ({
          signup_id: signup.id,
          flag_type: f.flag_type,
          detail: f.detail,
        })),
      );
    }

    if (deviceFpHash) {
      await supabase.from('referral_device_registry').upsert({
        device_fp_hash: deviceFpHash,
        supabase_user_id: body.supabase_user_id,
        last_seen_at: new Date().toISOString(),
      }, { onConflict: 'device_fp_hash,supabase_user_id' });
    }

    if (oauthSubjectHash && fraudInput.oauthProvider) {
      await supabase.from('referral_oauth_registry').upsert({
        oauth_provider: fraudInput.oauthProvider,
        oauth_subject_hash: oauthSubjectHash,
        supabase_user_id: body.supabase_user_id,
      }, { onConflict: 'oauth_provider,oauth_subject_hash' });
    }

    await bumpCodeCounters(supabase, codeRow.id, status === 'valid');
    await refreshPartnerDaily(supabase, codeRow.partner_id, signupDate);

    if (fraud.rejected) {
      await createFraudAlert(supabase, {
        signupId: signup.id,
        partnerId: codeRow.partner_id,
        codeId: codeRow.id,
        refCode,
        partnerDisplayName: partner.display_name,
        flags: fraud.flags,
        metadata: {
          supabase_user_id: body.supabase_user_id,
          mysql_user_id: body.mysql_user_id,
          email_domain: body.email.split('@')[1],
        },
      });
    }

    if (body.device_fp) {
      await markPendingClaimed(supabase, body.device_fp, body.supabase_user_id);
    }

    return jsonResponse(req, {
      success: true,
      attributed: true,
      signup_id: signup.id,
      status,
      counts_as_valid: status === 'valid',
      fraud_detected: fraud.rejected,
      flag_types: fraud.flags.map((f) => f.flag_type),
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'Error interno';
    const status = msg.includes('No autorizado') ? 401 : 500;
    return errorResponse(req, msg, status);
  }
});

const DEFAULT_ORIGINS = [
  'https://arcusx.pro',
  'https://www.arcusx.pro',
  'http://localhost:5173',
  'http://127.0.0.1:5173',
];

export function corsHeaders(req: Request): HeadersInit {
  const origin = req.headers.get('Origin') ?? '';
  const allowed = Deno.env.get('REFERRAL_CORS_ORIGINS')?.split(',').map((s) => s.trim()) ??
    DEFAULT_ORIGINS;
  const ok = allowed.includes(origin) || allowed.includes('*');
  return {
    'Access-Control-Allow-Origin': ok ? (origin || allowed[0]) : allowed[0],
    'Access-Control-Allow-Headers':
      'authorization, x-client-info, apikey, content-type, x-referral-internal-secret',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  };
}

export function handleOptions(req: Request): Response | null {
  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers: corsHeaders(req) });
  }
  return null;
}

export function jsonResponse(
  req: Request,
  body: unknown,
  status = 200,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders(req), 'Content-Type': 'application/json' },
  });
}

export function errorResponse(
  req: Request,
  message: string,
  status = 400,
): Response {
  return jsonResponse(req, { success: false, message }, status);
}

const encoder = new TextEncoder();

function salt(): string {
  return Deno.env.get('REFERRAL_HASH_SALT') ?? 'arcusx-referral-v1';
}

export async function sha256Hex(input: string): Promise<string> {
  const data = encoder.encode(input);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

export async function hashWithSalt(value: string): Promise<string> {
  if (!value?.trim()) return '';
  return sha256Hex(`${salt()}:${value.trim().toLowerCase()}`);
}

export function normalizeRefCode(code: string): string {
  return code.trim().toUpperCase().replace(/\s+/g, '-');
}

export function clientIp(req: Request): string {
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0]?.trim() ?? '';
  return req.headers.get('cf-connecting-ip') ??
    req.headers.get('x-real-ip') ??
    '';
}

import { supabaseService } from './referral-db.ts';

export function isReferralInternalCaller(req: Request): boolean {
  const expected = Deno.env.get('REFERRAL_INTERNAL_SECRET');
  if (!expected) return false;
  const got = req.headers.get('x-referral-internal-secret') ??
    req.headers.get('X-Referral-Internal-Secret');
  return got === expected;
}

/**
 * Permite atribución desde PHP (secret interno) o desde el cliente tras OAuth (JWT del usuario).
 */
export async function assertReferralCaller(
  req: Request,
  supabaseUserId: string,
): Promise<void> {
  if (isReferralInternalCaller(req)) return;

  const auth = req.headers.get('Authorization') ?? '';
  const token = auth.replace(/^Bearer\s+/i, '').trim();
  if (!token) {
    throw new Error('No autorizado');
  }

  const supabase = supabaseService();
  const { data: { user }, error } = await supabase.auth.getUser(token);
  if (error || !user?.id || user.id !== supabaseUserId) {
    throw new Error('No autorizado');
  }
}

import { createClient, type SupabaseClient } from '@supabase/supabase-js';

export function supabaseService(): SupabaseClient {
  const url = Deno.env.get('SUPABASE_URL') ??
    Deno.env.get('ARCUSX_SUPABASE_URL');
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ??
    Deno.env.get('ARCUSX_SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !key) {
    throw new Error(
      'Supabase URL/service key requeridos (SUPABASE_* o ARCUSX_SUPABASE_*)',
    );
  }
  return createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export async function refreshPartnerDaily(
  supabase: SupabaseClient,
  partnerId: string,
  statDate: string,
): Promise<void> {
  await supabase.rpc('referral_refresh_daily_totals', {
    p_partner_id: partnerId,
    p_stat_date: statDate,
  });
}

export async function bumpCodeCounters(
  supabase: SupabaseClient,
  codeId: string,
  valid: boolean,
): Promise<void> {
  const { data: row } = await supabase
    .from('referral_codes')
    .select('signup_count, valid_signup_count')
    .eq('id', codeId)
    .single();

  if (!row) return;

  await supabase
    .from('referral_codes')
    .update({
      signup_count: (row.signup_count ?? 0) + 1,
      valid_signup_count: valid
        ? (row.valid_signup_count ?? 0) + 1
        : row.valid_signup_count,
      updated_at: new Date().toISOString(),
    })
    .eq('id', codeId);
}

import type { SupabaseClient } from '@supabase/supabase-js';
import { hashWithSalt } from './referral-crypto.ts';

export interface FraudInput {
  refCode: string;
  supabaseUserId: string;
  mysqlUserId: number | null;
  email: string;
  isNewUser: boolean;
  signupIp: string;
  deviceFp: string;
  userAgent: string;
  oauthProvider: string;
  oauthSubject: string;
}

export interface FraudFlag {
  flag_type: string;
  detail: Record<string, unknown>;
}

export interface FraudResult {
  flags: FraudFlag[];
  rejected: boolean;
  rejection_reason: string | null;
}

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com',
  'guerrillamail.com',
  'tempmail.com',
  '10minutemail.com',
  'yopmail.com',
  'throwaway.email',
  'trashmail.com',
]);

export function assertInternalSecret(req: Request): void {
  const expected = Deno.env.get('REFERRAL_INTERNAL_SECRET');
  if (!expected) {
    throw new Error('REFERRAL_INTERNAL_SECRET no configurado');
  }
  const got = req.headers.get('x-referral-internal-secret') ??
    req.headers.get('X-Referral-Internal-Secret');
  if (got !== expected) {
    throw new Error('No autorizado');
  }
}

export async function runFraudChecks(
  supabase: SupabaseClient,
  input: FraudInput,
  codeRow: { id: string; partner_id: string; code: string },
): Promise<FraudResult> {
  const flags: FraudFlag[] = [];

  if (codeRow.code.startsWith('TRAP-') || codeRow.code.startsWith('HONEYPOT')) {
    flags.push({
      flag_type: 'honeypot',
      detail: { code: codeRow.code },
    });
  }

  if (!input.isNewUser) {
    flags.push({
      flag_type: 'existing_email',
      detail: { email_domain: input.email.split('@')[1] ?? '' },
    });
  }

  const emailDomain = (input.email.split('@')[1] ?? '').toLowerCase();
  if (DISPOSABLE_DOMAINS.has(emailDomain)) {
    flags.push({ flag_type: 'disposable_email', detail: { domain: emailDomain } });
  }

  const { data: priorUser } = await supabase
    .from('referral_signups')
    .select('id, status')
    .eq('supabase_user_id', input.supabaseUserId)
    .maybeSingle();

  if (priorUser) {
    flags.push({
      flag_type: 'duplicate_user',
      detail: { prior_status: priorUser.status },
    });
  }

  const ipHash = await hashWithSalt(input.signupIp);
  if (ipHash) {
    const since24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();

    const { count: ipSameCode } = await supabase
      .from('referral_signups')
      .select('id', { count: 'exact', head: true })
      .eq('code_id', codeRow.id)
      .eq('signup_ip_hash', ipHash)
      .gte('registered_at', since24h);

    if ((ipSameCode ?? 0) >= 3) {
      flags.push({
        flag_type: 'ip_cluster',
        detail: { count_24h: ipSameCode, scope: 'same_code' },
      });
    }

    const { count: ipGlobal } = await supabase
      .from('referral_signups')
      .select('id', { count: 'exact', head: true })
      .eq('signup_ip_hash', ipHash)
      .gte('registered_at', since24h);

    if ((ipGlobal ?? 0) >= 8) {
      flags.push({
        flag_type: 'ip_global_abuse',
        detail: { count_24h: ipGlobal },
      });
    }
  }

  const deviceHash = await hashWithSalt(input.deviceFp);
  if (deviceHash) {
    const { data: deviceHits } = await supabase
      .from('referral_device_registry')
      .select('supabase_user_id')
      .eq('device_fp_hash', deviceHash)
      .neq('supabase_user_id', input.supabaseUserId)
      .limit(5);

    if (deviceHits && deviceHits.length > 0) {
      flags.push({
        flag_type: 'device_fp_reuse',
        detail: {
          other_accounts: deviceHits.length,
          user_ids: deviceHits.map((r) => r.supabase_user_id),
        },
      });
    }

    const since7d = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
    const { count: deviceVelocity } = await supabase
      .from('referral_signups')
      .select('id', { count: 'exact', head: true })
      .eq('device_fp_hash', deviceHash)
      .gte('registered_at', since7d);

    if ((deviceVelocity ?? 0) >= 2) {
      flags.push({
        flag_type: 'device_velocity',
        detail: { signups_7d: deviceVelocity },
      });
    }
  }

  if (input.oauthProvider && input.oauthSubject) {
    const subjectHash = await hashWithSalt(
      `${input.oauthProvider}:${input.oauthSubject}`,
    );
    const { data: oauthHit } = await supabase
      .from('referral_oauth_registry')
      .select('supabase_user_id')
      .eq('oauth_provider', input.oauthProvider)
      .eq('oauth_subject_hash', subjectHash)
      .neq('supabase_user_id', input.supabaseUserId)
      .maybeSingle();

    if (oauthHit) {
      flags.push({
        flag_type: 'oauth_subject_reuse',
        detail: { provider: input.oauthProvider },
      });
    }
  }

  const since1h = new Date(Date.now() - 60 * 60 * 1000).toISOString();
  const { count: codeVelocity } = await supabase
    .from('referral_signups')
    .select('id', { count: 'exact', head: true })
    .eq('code_id', codeRow.id)
    .gte('registered_at', since1h);

  if ((codeVelocity ?? 0) >= 6) {
    flags.push({
      flag_type: 'velocity_code',
      detail: { signups_1h: codeVelocity },
    });
  }

  const criticalTypes = new Set([
    'honeypot',
    'existing_email',
    'duplicate_user',
    'disposable_email',
    'device_fp_reuse',
    'oauth_subject_reuse',
    'ip_cluster',
    'ip_global_abuse',
    'device_velocity',
    'velocity_code',
  ]);

  const blocking = flags.filter((f) => criticalTypes.has(f.flag_type));
  const rejected = blocking.length > 0;
  const rejection_reason = rejected
    ? blocking.map((f) => f.flag_type).join(', ')
    : null;

  return { flags, rejected, rejection_reason };
}

export async function createFraudAlert(
  supabase: SupabaseClient,
  params: {
    signupId: string | null;
    partnerId: string;
    codeId: string;
    refCode: string;
    partnerDisplayName: string;
    flags: FraudFlag[];
    metadata: Record<string, unknown>;
  },
): Promise<void> {
  const flagTypes = params.flags.map((f) => f.flag_type);
  const title = `Referido rechazado · ${params.partnerDisplayName}`;
  const message =
    `Código ${params.refCode}: intento de registro bloqueado (${flagTypes.join(', ')}). No cuenta en métricas.`;

  await supabase.from('referral_fraud_alerts').insert({
    signup_id: params.signupId,
    partner_id: params.partnerId,
    code_id: params.codeId,
    ref_code: params.refCode,
    partner_display_name: params.partnerDisplayName,
    severity: flagTypes.includes('honeypot') ? 'critical' : 'high',
    title,
    message,
    flag_types: flagTypes,
    metadata: params.metadata,
  });

  const adminMysqlIds = (Deno.env.get('REFERRAL_ADMIN_MYSQL_IDS') ?? '')
    .split(',')
    .map((s) => parseInt(s.trim(), 10))
    .filter((n) => Number.isFinite(n) && n > 0);

  if (adminMysqlIds.length > 0) {
    const rows = adminMysqlIds.map((user_id_mysql) => ({
      user_id_mysql,
      title,
      message,
      type: 'warning' as const,
    }));
    await supabase.from('arcusx_notifications').insert(rows);
  }
}

import type { SupabaseClient } from '@supabase/supabase-js';
import { hashWithSalt, normalizeRefCode } from './referral-crypto.ts';

const DEVICE_FP_RE = /^ax-[a-z0-9]+-[a-z0-9]+$/i;
const BIND_RATE_LIMIT_PER_IP_HOUR = 40;

export function assertValidDeviceFp(deviceFp: string): void {
  const fp = deviceFp?.trim() ?? '';
  if (!DEVICE_FP_RE.test(fp) || fp.length > 80) {
    throw new Error('device_fp inválido');
  }
}

export async function assertActiveReferralCode(
  supabase: SupabaseClient,
  refCode: string,
): Promise<void> {
  const code = normalizeRefCode(refCode);
  const { data: row } = await supabase
    .from('referral_codes')
    .select('id, expires_at, referral_partners!inner(is_active)')
    .eq('code', code)
    .eq('is_active', true)
    .maybeSingle();

  if (!row) throw new Error('Código no válido');

  const partner = row.referral_partners as { is_active: boolean };
  if (!partner?.is_active) throw new Error('Código no válido');

  if (row.expires_at && new Date(row.expires_at) < new Date()) {
    throw new Error('Código expirado');
  }
}

async function assertBindRateLimit(
  supabase: SupabaseClient,
  signupIp: string,
): Promise<void> {
  if (!signupIp?.trim()) return;
  const ipHash = await hashWithSalt(signupIp);
  if (!ipHash) return;
  const since = new Date(Date.now() - 60 * 60 * 1000).toISOString();
  const { count } = await supabase
    .from('referral_pending_attributions')
    .select('device_fp', { count: 'exact', head: true })
    .eq('signup_ip_hash', ipHash)
    .gte('created_at', since);
  if ((count ?? 0) >= BIND_RATE_LIMIT_PER_IP_HOUR) {
    throw new Error('Demasiados intentos; espera un momento');
  }
}

export interface PendingBindInput {
  refCode: string;
  deviceFp: string;
  signupIp?: string;
  userAgent?: string;
}

export async function bindPendingReferral(
  supabase: SupabaseClient,
  input: PendingBindInput,
): Promise<{ ref_code: string }> {
  const refCode = normalizeRefCode(input.refCode);
  const deviceFp = input.deviceFp?.trim() ?? '';
  if (!refCode || !deviceFp) {
    throw new Error('ref_code y device_fp requeridos');
  }
  assertValidDeviceFp(deviceFp);
  await assertActiveReferralCode(supabase, refCode);
  await assertBindRateLimit(supabase, input.signupIp ?? '');

  const signupIpHash = input.signupIp ? await hashWithSalt(input.signupIp) : null;
  const userAgentHash = input.userAgent ? await hashWithSalt(input.userAgent) : null;
  const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

  const { error } = await supabase.from('referral_pending_attributions').upsert(
    {
      device_fp: deviceFp,
      ref_code: refCode,
      signup_ip_hash: signupIpHash,
      user_agent_hash: userAgentHash,
      expires_at: expiresAt,
      claimed_at: null,
      supabase_user_id: null,
    },
    { onConflict: 'device_fp' },
  );

  if (error) throw new Error(error.message);
  return { ref_code: refCode };
}

export async function resolvePendingRefCode(
  supabase: SupabaseClient,
  deviceFp: string,
): Promise<string | null> {
  const fp = deviceFp?.trim();
  if (!fp) return null;

  const { data } = await supabase
    .from('referral_pending_attributions')
    .select('ref_code, expires_at, claimed_at')
    .eq('device_fp', fp)
    .maybeSingle();

  if (!data?.ref_code || data.claimed_at) return null;
  if (data.expires_at && new Date(data.expires_at) < new Date()) return null;
  return normalizeRefCode(data.ref_code);
}

export async function markPendingClaimed(
  supabase: SupabaseClient,
  deviceFp: string,
  supabaseUserId: string,
): Promise<void> {
  const fp = deviceFp?.trim();
  if (!fp) return;
  await supabase
    .from('referral_pending_attributions')
    .update({
      claimed_at: new Date().toISOString(),
      supabase_user_id: supabaseUserId,
    })
    .eq('device_fp', fp);
}
